package store

import (
	"context"
	"errors"
	"fmt"
)

// ErrNoClaim is what callers match on when a project has no owner yet.
var ErrNoClaim = errors.New("no claim for project")

// Owner returns the team slug that claimed project.
// Callers distinguish "nobody owns it" from a database fault with errors.Is.
func (s *Store) Owner(ctx context.Context, project string) (string, error) {
	var slug string
	err := s.pool.QueryRow(ctx,
		`SELECT team_slug FROM team_claims WHERE project_key = $1`,
		project).Scan(&slug)
	if errors.Is(err, errNoRows) {
		return "", fmt.Errorf("owner of %q: %w", project, err)
	}
	if err != nil {
		return "", fmt.Errorf("owner of %q: %w", project, ErrNoClaim)
	}
	return slug, nil
}
